app.MapPut("/api/products/{id:int}", async (int id, ProductUpdate dto,
    [FromHeader(Name = "If-Match")] string? ifMatch, AppDbContext db, CancellationToken ct) =>
{
    if (ifMatch is null) return Results.StatusCode(StatusCodes.Status428PreconditionRequired);
    var p = await db.Products.FindAsync([id], ct);
    if (p is null) return Results.NotFound();
    db.Entry(p).Property(x => x.Version).OriginalValue = ETags.ToVersion(ifMatch);
    p.Apply(dto);
    try { await db.SaveChangesAsync(ct); }
    catch (DbUpdateConcurrencyException) { return Results.StatusCode(StatusCodes.Status412PreconditionFailed); }
    return Results.NoContent();
});

